"""Independent certificate validator written straight from PROTOCOL.md."""


def valid_plan(n, links, demands, period, envelope, plan):
    """demands: dict vertex->r_v ; envelope: dict link->rate"""
    if set(plan) != {'trees', 'routes', 'recipes'}:
        return False, 'plan fields'
    C = sorted(demands)
    pc = set(C)
    D = sum(demands.values())
    trees, routes, recipes = plan['trees'], plan['routes'], plan['recipes']
    if len(trees) > 8192 or len(routes) > 32768 or len(recipes) > 65536:
        return False, 'representation budget'
    per_root = {v: 0 for v in C}
    L = {}
    for rec in trees:
        if not isinstance(rec, list) or len(rec) != 3:
            return False, 'tree shape'
        root, count, edges = rec
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0 or count > D:
            return False, 'tree count'
        if root not in pc:
            return False, 'tree root'
        if not isinstance(edges, list) or len(edges) != len(C) - 1:
            return False, 'tree edge count'
        seen = set(); indeg = {}; adj = {}
        for e in edges:
            if not isinstance(e, list) or len(e) != 2:
                return False, 'edge shape'
            a, b = e
            if a not in pc or b not in pc or a == b:
                return False, 'edge endpoints'
            if (a, b) in seen:
                return False, 'duplicate edge'
            seen.add((a, b))
            indeg[b] = indeg.get(b, 0) + 1
            adj.setdefault(a, []).append(b)
        if indeg.get(root, 0) != 0:
            return False, 'root indegree'
        for v in C:
            if v != root and indeg.get(v, 0) != 1:
                return False, 'indegree'
        stack = [root]; got = {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in got:
                    got.add(y); stack.append(y)
        if got != pc:
            return False, 'reachability'
        per_root[root] += count
        for pair in seen:
            L[pair] = L.get(pair, 0) + count
    for v in C:
        if per_root[v] != demands[v]:
            return False, f'root {v} weight {per_root[v]} != {demands[v]}'
    # recipes
    m = len(links)
    st = [None] * len(recipes); en = [None] * len(recipes); seq = [None] * len(recipes)

    def expand(i, guard):
        if seq[i] is not None:
            return True
        if guard > 5000:
            return False
        node = recipes[i]
        if not isinstance(node, list) or len(node) != 3:
            return False
        kind = node[0]
        if kind == 0:
            l, d = node[1], node[2]
            if not isinstance(l, int) or isinstance(l, bool) or not (0 <= l < m):
                return False
            if d not in (0, 1):
                return False
            u, v, _c = links[l]
            st[i], en[i] = (u, v) if d == 0 else (v, u)
            seq[i] = [(l, d)]
            return True
        if kind == 1:
            a, b = node[1], node[2]
            if not (0 <= a < len(recipes)) or not (0 <= b < len(recipes)):
                return False
            if seq[a] is None:
                if not expand(a, guard + 1):
                    return False
            if seq[b] is None:
                if not expand(b, guard + 1):
                    return False
            if en[a] != st[b]:
                return False
            if en[a] in pc:
                return False, 'join at participant'
            st[i], en[i] = st[a], en[b]
            seq[i] = seq[a] + seq[b]
            return True
        return False
    # cycle detection: no node may depend on itself
    for i in range(len(recipes)):
        # detect cycles first
        stack = [i]; seen = set()
        while stack:
            x = stack.pop()
            node = recipes[x]
            if not isinstance(node, list) or len(node) != 3 or node[0] not in (0, 1):
                return False, 'recipe node shape'
            if node[0] == 1:
                for y in (node[1], node[2]):
                    if not isinstance(y, int) or isinstance(y, bool) or not (0 <= y < len(recipes)):
                        return False, 'recipe ref'
                    if y == i:
                        return False, 'cycle'
                    stack.append(y)
        if not expand(i, 0)[0] if isinstance(expand(i, 0), tuple) else not expand(i, 0):
            return False, 'recipe expand'
    per_pair = {}; loads = {}
    for rec in routes:
        if not isinstance(rec, list) or len(rec) != 4:
            return False, 'route shape'
        u, v, count, rid = rec
        for x in (u, v, count, rid):
            if not isinstance(x, int) or isinstance(x, bool):
                return False, 'route types'
        if u not in pc or v not in pc or u == v:
            return False, 'route endpoints'
        if count < 1 or count > D:
            return False, 'route count'
        if not (0 <= rid < len(recipes)):
            return False, 'recipe id'
        if st[rid] != u or en[rid] != v:
            return False, 'route walk'
        per_pair[(u, v)] = per_pair.get((u, v), 0) + count
        for pair in seq[rid]:
            loads[pair] = loads.get(pair, 0) + count
    for pair in set(list(per_pair) + list(L)):
        if per_pair.get(pair, 0) != L.get(pair, 0):
            return False, f'pair {pair} routes {per_pair.get(pair,0)} != L {L.get(pair,0)}'
    cl = [period * envelope.get(l, 0) for l in range(m)]
    for l in range(m):
        for d in (0, 1):
            if loads.get((l, d), 0) > cl[l]:
                return False, f'link {l} dir {d} load {loads.get((l,d),0)} > {cl[l]}'
    return True, 'ok'


def valid_cut(n, links, demands, period, envelope, S):
    """strict deficient cut certificate"""
    if not isinstance(S, list) or len(set(S)) != len(S):
        return False, 'cut distinct'
    pc = set(demands)
    for v in S:
        if not isinstance(v, int) or isinstance(v, bool) or not (0 <= v < n):
            return False, 'cut vertex range'
    inside = set(S)
    got = [v for v in pc if v in inside]
    if not got or len(got) == len(pc):
        return False, 'cut must separate participants'
    cap = 0
    for l, (u, v, _c) in enumerate(links):
        if (u in inside) != (v in inside):
            cap += period * envelope.get(l, 0)
    dem = sum(demands[v] for v in got)
    if not cap < dem:
        return False, f'not strict: cap {cap} dem {dem}'
    return True, 'ok'


def valid_capacity(links, caps, used_fn, period, envelope, s, e, w):
    l = w.get('link'); t = w.get('time'); u = w.get('used'); c = w.get('capacity')
    for x in (l, t, u, c):
        if not isinstance(x, int) or isinstance(x, bool):
            return False, 'types'
    if not (0 <= l < len(links)):
        return False, 'link range'
    if not (s <= t < e):
        return False, 'time window'
    if u != used_fn(l, t) + envelope.get(l, 0):
        return False, 'used mismatch'
    if c != caps[l]:
        return False, 'capacity mismatch'
    if not u > c:
        return False, 'not violating'
    return True, 'ok'
